package com.colavite.gestor_investimento.controller;
import com.colavite.gestor_investimento.entity.*; import com.colavite.gestor_investimento.repository.*; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.http.MediaType; import org.springframework.test.context.ActiveProfiles; import org.springframework.test.web.servlet.MockMvc; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.time.Instant; import static org.assertj.core.api.Assertions.assertThat; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") @Transactional class OperacaoControllerTest { @Autowired MockMvc mockMvc; @Autowired CarteiraRepository carteiras; @Autowired AcaoRepository acoes; @Autowired OperacaoRepository operacoes;
 @Test void criaEConsultaOperacao() throws Exception { var c=carteiras.saveAndFlush(new Carteira("Carteira API","CARTEIRA API",null)); var a=acoes.saveAndFlush(new Acao("PETR4","Petrobras",Mercado.BRASIL,new BigDecimal("30"),Instant.now())); var body="{\"carteiraId\":"+c.getId()+",\"acaoId\":"+a.getId()+",\"tipo\":\"COMPRA\",\"quantidade\":10,\"precoUnitario\":30,\"dataOperacao\":\"2026-09-01T12:00:00Z\"}"; var result=mockMvc.perform(post("/operacoes").contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isCreated()).andExpect(jsonPath("$.ticker").value("PETR4")).andReturn(); var id=Long.valueOf(result.getResponse().getHeader("Location").replaceAll(".*/", "")); mockMvc.perform(get("/operacoes/"+id)).andExpect(status().isOk()).andExpect(jsonPath("$.tipo").value("COMPRA")); mockMvc.perform(get("/carteiras/"+c.getId()+"/operacoes")).andExpect(status().isOk()).andExpect(jsonPath("$[0].acaoId").value(a.getId())); }
 @Test void rejeitaRequestInvalidoENaoEncontrado() throws Exception { mockMvc.perform(post("/operacoes").contentType(MediaType.APPLICATION_JSON).content("{\"tipo\":\"COMPRA\"}" )).andExpect(status().isBadRequest()); mockMvc.perform(get("/operacoes/999999")).andExpect(status().isNotFound()); }
 @Test void aceitaQuantidadeFracionariaEPrecoComOitoCasas() throws Exception { var c=carteiras.saveAndFlush(new Carteira("Carteira decimal","CARTEIRA DECIMAL",null)); var a=acoes.saveAndFlush(new Acao("WEGE3","Weg",Mercado.BRASIL,new BigDecimal("30"),Instant.now())); var body="{\"carteiraId\":"+c.getId()+",\"acaoId\":"+a.getId()+",\"tipo\":\"COMPRA\",\"quantidade\":0.12345678,\"precoUnitario\":100.00000001,\"dataOperacao\":\"2026-09-01T12:00:00Z\"}"; mockMvc.perform(post("/operacoes").contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isCreated()).andExpect(jsonPath("$.quantidade").value(0.12345678)); }
 @Test void rejeitaValoresNumericosForaDaCapacidadeOuNaoPositivos() throws Exception { var c=carteiras.saveAndFlush(new Carteira("Carteira limites","CARTEIRA LIMITES",null)); var a=acoes.saveAndFlush(new Acao("ITUB4","Itau",Mercado.BRASIL,new BigDecimal("30"),Instant.now())); long antes=operacoes.count(); for (String valores : new String[]{"0.123456789,30","100000000000,30","0,30","-1,30","1,30.123456789","1,100000000000","1,0","1,-30"}) { String[] partes=valores.split(","); var body="{\"carteiraId\":"+c.getId()+",\"acaoId\":"+a.getId()+",\"tipo\":\"COMPRA\",\"quantidade\":"+partes[0]+",\"precoUnitario\":"+partes[1]+",\"dataOperacao\":\"2026-09-01T12:00:00Z\"}"; mockMvc.perform(post("/operacoes").contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isBadRequest()); } assertThat(operacoes.count()).isEqualTo(antes); }
}
